        private static (int Year, string State, int District, long VotesR, long VotesD, long VotesOther, long VotesTotal, long OwnR, long OwnD, int CandsR, int CandsD, long FinalR, long FinalD, string Winner, string Flags)[] JoinHouseDistricts(params (int, string, int, long, long, long, long, long, long, int, int, long, long, string, string)[][] parts)
        {
            int n = 0;
            foreach (var p in parts) { n += p.Length; }
            var all = new (int Year, string State, int District, long VotesR, long VotesD, long VotesOther, long VotesTotal, long OwnR, long OwnD, int CandsR, int CandsD, long FinalR, long FinalD, string Winner, string Flags)[n];
            int at = 0;
            foreach (var p in parts) { for (int i = 0; i < p.Length; i++) { all[at++] = p[i]; } }
            return all;
        }

